SELECT "companyid", "status", "name", "industry", "sprating", "islowgrade", "ceo", "addressline1", "addressline2", "postalcode", "city", "stateprov", "country", "description", "foundingdate", "iscurrent", "batchid", "effectivedate", "enddate", CAST(ROW_NUMBER() OVER (ORDER BY companyid, effectivedate) AS int) AS "sk_companyid" FROM (SELECT TRY_CAST((TRY_CAST(f.CIK AS INTEGER)) AS int) AS "companyid", TRY_CAST((CAST(f.Status AS CHAR(10))) AS char(10)) AS "status", TRY_CAST((CAST(f.CompanyName AS CHAR(60))) AS char(60)) AS "name", TRY_CAST((CAST(i.IN_NAME AS CHAR(50))) AS char(50)) AS "industry", TRY_CAST((f.SPrating) AS char(4)) AS "sprating", TRY_CAST((CASE
  WHEN f.SPrating IS NULL THEN NULL
  WHEN upper(f.SPrating) IN ('BB+','BB','BB-','B+','B','B-','CCC+','CCC','CCC-','CC','C','D') THEN TRUE
  WHEN upper(f.SPrating) IN ('AAA','AA+','AA','AA-','A+','A','A-','BBB+','BBB','BBB-') THEN FALSE
  ELSE NULL
END) AS boolean) AS "islowgrade", TRY_CAST((f.CEOname) AS char(100)) AS "ceo", TRY_CAST((f.AddrLine1) AS char(80)) AS "addressline1", TRY_CAST((CAST(f.AddrLine2 AS VARCHAR(80))) AS char(80)) AS "addressline2", TRY_CAST((CAST(f.PostalCode AS CHAR(12))) AS char(12)) AS "postalcode", TRY_CAST((CAST(f.City AS CHAR(25))) AS char(25)) AS "city", TRY_CAST((CAST(f.StateProvince AS CHAR(20))) AS char(20)) AS "stateprov", TRY_CAST((CAST(f.Country AS CHAR(24))) AS char(24)) AS "country", TRY_CAST((CAST(f.Description AS CHAR(150))) AS char(150)) AS "description", TRY_CAST((CAST(strptime(f.FoundingDate, '%Y%m%d') AS DATE)) AS date) AS "foundingdate", TRY_CAST((f.PTS = MAX(f.PTS) OVER (PARTITION BY f.CIK)) AS boolean) AS "iscurrent", TRY_CAST((CAST(NULL AS DECIMAL(5))) AS decimal(5)) AS "batchid", TRY_CAST((CASE WHEN f.PTS ~ '^[0-9]{8}-[0-9]{6}$' THEN CAST(strptime(f.PTS, '%Y%m%d-%H%M%S') AS DATE) ELSE NULL END) AS date) AS "effectivedate", TRY_CAST((CAST('9999-12-31' AS DATE)) AS date) AS "enddate" FROM FinwireCMP AS f INNER JOIN Industry AS i ON f.IndustryID = i.IN_ID INNER JOIN StatusType AS s ON f.Status = s.ST_ID)
